def solve(path):
    """Simplify an absolute Unix path.
    Implements the standard algorithm: split by '/', use a stack to process
    components ignoring empty and '.'; '..' pops if possible.
    Returns the canonical path without trailing slash (except root)."""
    # Ensure input is a string
    if not isinstance(path, str):
        raise TypeError("Path must be a string")
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root (do nothing)
        else:
            stack.append(part)
    # Build the result
    result = '/' + '/'.join(stack)
    # Remove trailing slash if not root
    if len(result) > 1 and result.endswith('/'):
        result = result[:-1]
    return result

