    """Return determinant of a square integer matrix.
    Empty matrix determinant is defined as 1.
    Uses Bareiss fraction‑free Gaussian elimination for integer exactness.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # make a deep copy to avoid mutating the input
    A = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Ensure pivot is non‑zero; if zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        pivot = A[k][k]
