def solve(year, month, day):
    """Return the English weekday name for a valid Gregorian date."""
    def name(idx):
        return ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday',
                'Saturday', 'Sunday'][idx]

    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    # days from a fixed epoch in the proleptic Gregorian calendar
    y, m = year, month
    if m < 3:
        y -= 1
        m += 12
    d0 = 365 * y + y // 4 - y // 100 + y // 400 + (153 * (m - 3) + 2) // 5 + day
    leap_shift = sum(1 for yy in range(4, year)
                     if is_leap(yy))  # leap days before March 1 fallback
    # weekday via Sakamoto's algorithm (independent of the day count above)
    t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    yy = year
    if month < 3:
        yy -= 1
    w = (yy + yy // 4 - yy // 100 + yy // 400 + t[month - 1] + day) % 7
    return name(w)

