def solve(grid):
    """Return the number of islands in a grid of 0s and 1s.
    Handles non‑rectangular (jagged) grids gracefully by using each row's length.
    Any value other than 1 is treated as water.
    """
    if not grid:
        return 0
    n = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore four directions
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < len(grid[nx]) and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

